script:
const fs=require('node:fs'),crypto=require('node:crypto');
const {snapshotSchema}=require('./lib/in-season/workspaceSchema');
const {timestampMicros}=require('./lib/projections/evidenceTime');
const {readBoundedFile,verifySourcePins}=require('../tasks/artifacts/rso-daily-beta-2026-11-08/saved-input-preflight-2026-11-09/inspect-saved-planning');
try {
 verifySourcePins();
 const bytes=readBoundedFile(process.argv[1],8000000), payload=JSON.parse(bytes.toString('utf8'));
 const parsed=snapshotSchema.safeParse(payload.snapshot);
 const same=(key)=>parsed.success && JSON.stringify(parsed.data[key])===JSON.stringify(payload.snapshot[key]);
 const report={version:'rso-retained-export-inspection-v1',historicalOnly:true,inputSha256:crypto.createHash('sha256').update(bytes).digest('hex'),inputBytes:bytes.length,
  recognizedExport:payload.version==='rso-planning-evidence-v1',snapshotSchemaAccepted:parsed.success,
  clocksPresentAndValid:['exportedAt','readerCheckedAt'].every(key=>timestampMicros(payload[key])!==null),
  preservedFields:Object.fromEntries(['rules','roster','lockedAssignments','realized','opponent'].map(key=>[key,same(key)])),
  rosterCount:Array.isArray(payload.snapshot?.roster)?payload.snapshot.roster.length:null,
  selectedMoveCount:Array.isArray(payload.intent?.steps)?payload.intent.steps.length:null,
  protectedPlayerCount:Array.isArray(payload.intent?.protectedPlayerIds)?payload.intent.protectedPlayerIds.length:null,
  hasProviderSnapshot:payload.providerSnapshot!==null,
  restorableBackup:false,currentAuthenticatedAcceptance:false,forecastUseGranted:false,
  limits:['historical_saved_input_only','export_is_not_a_restorable_workspace','empty_intent_cannot_prove_selected_move_continuity','no_response_only_bridge_proof','manager_private_acceptance_still_required']};
 process.stdout.write(JSON.stringify(report,null,2)+'\n');process.exitCode=parsed.success && report.recognizedExport && Object.values(report.preservedFields).every(Boolean)?0:1;
} catch {process.stderr.write('retained_export_inspection_failed\n');process.exitCode=2;}
